package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"go/types"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"text/template"
)

const (
	rootDir = "."
	outFile = "reset.gen.go"
)

const TemplateStr = `
// Code generated by go generate; DO NOT EDIT.

package {{.Package}}
{{range .Structs}}
func (s *{{.Name}}) Reset() {
	if s == nil {
		return
	}
{{- range .Fields}}
{{template "field" .}}
{{- end}}
}
{{end}}

{{- define "field"}}
{{- if eq .Kind "primitive"}}s.{{.Name}} = {{.Zero}}
{{- else if eq .Kind "slice"}}s.{{.Name}} = s.{{.Name}}[:0]
{{- else if eq .Kind "array"}}clear(s.{{.Name}}[:])
{{- else if eq .Kind "map"}}clear(s.{{.Name}})
{{- else if eq .Kind "ptr"}}if s.{{.Name}} != nil {
	*s.{{.Name}} = {{.Zero}}
}
{{- else if eq .Kind "nested"}}if r, ok := any(&s.{{.Name}}).(interface{ Reset() }); ok {
	r.Reset()
}
{{- else if eq .Kind "ptrnested"}}if r, ok := any(s.{{.Name}}).(interface{ Reset() }); ok && s.{{.Name}} != nil {
	r.Reset()
}
{{- end}}
{{- end}}`

var tmpl = template.Must(template.New("reset").Parse(TemplateStr))

type field struct {
	Name string
	Kind string
	Zero string
}
type structInfo struct {
	Name   string
	Fields []field
}

type pkgInfo struct {
	Package string
	Structs []*structInfo
}

func main() {
	pkgs := map[string]*pkgInfo{}

	fset := token.NewFileSet()
	err := filepath.WalkDir(rootDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			name := d.Name()
			if path != rootDir && strings.HasPrefix(name, ".") {
				return filepath.SkipDir
			}
			return nil
		}

		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") || d.Name() == "reset.gen.go" {
			return nil
		}

		file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			fmt.Printf("parse %s: %v\n", path, err)
			return nil
		}
		dir := filepath.Dir(path)
		ast.Inspect(file, func(n ast.Node) bool {
			genDecl, ok := n.(*ast.GenDecl)
			if !ok || genDecl.Tok != token.TYPE {
				return true
			}

			for _, spec := range genDecl.Specs {
				typeSpec, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				st, isStruct := typeSpec.Type.(*ast.StructType)
				if !isStruct {
					continue
				}
				if !hasMarker(genDecl.Doc, typeSpec.Doc) {
					continue
				}
				p := pkgs[dir]
				if p == nil {
					p = &pkgInfo{Package: file.Name.Name}
					pkgs[dir] = p
				}
				p.Structs = append(p.Structs, &structInfo{Name: typeSpec.Name.Name, Fields: buildFields(st)})
			}
			return false
		})

		return nil
	})

	if err != nil {
		log.Fatal(err)
	}

	for dir, p := range pkgs {
		if err := generate(dir, p); err != nil {
			log.Fatalf("%s: %v", dir, err)
		}
	}
}

func hasMarker(groups ...*ast.CommentGroup) bool {

	for _, group := range groups {
		if group == nil {
			continue
		}
		for _, comment := range group.List {
			if strings.TrimSpace(strings.TrimPrefix(comment.Text, "//")) == "generate:reset" {
				return true
			}
		}
	}
	return false
}

func buildFields(st *ast.StructType) []field {
	var fields []field

	for _, f := range st.Fields.List {
		kind, zero := classify(f.Type)
		if kind == "" {
			continue
		}
		for _, name := range fieldNames(f) {
			fields = append(fields, field{Name: name, Kind: kind, Zero: zero})
		}
	}
	return fields
}

func fieldNames(f *ast.Field) []string {
	if len(f.Names) == 0 {
		t := strings.TrimLeft(types.ExprString(f.Type), "*")
		return []string{t[strings.LastIndex(t, ".")+1:]}
	}
	var names []string
	for _, name := range f.Names {
		if name.Name != "_" {
			names = append(names, name.Name)
		}
	}
	return names
}

var zeroValues = map[string]string{
	"bool": "false", "string": `""`,
	"int": "0", "int8": "0", "int16": "0", "int32": "0", "int64": "0",
	"uint": "0", "uint8": "0", "uint16": "0", "uint32": "0", "uint64": "0",
	"uintptr": "0", "byte": "0", "rune": "0",
	"float32": "0", "float64": "0",
	"error": "nil", "any": "nil",
}

func classify(typ ast.Expr) (kind, zero string) {
	switch t := typ.(type) {
	case *ast.Ident:
		if z, ok := zeroValues[t.Name]; ok {
			return "primitive", z
		}
		return "nested", ""
	case *ast.SelectorExpr:
		return "nested", ""
	case *ast.ArrayType:
		if t.Len == nil {
			return "slice", ""
		}
		return "array", ""
	case *ast.MapType:
		return "map", ""
	case *ast.StarExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			if z, ok := zeroValues[id.Name]; ok {
				return "ptr", z
			}
		}
		return "ptrnested", ""
	}
	return "", ""
}

func generate(dir string, pkg *pkgInfo) error {
	sort.Slice(pkg.Structs, func(i, j int) bool {
		return pkg.Structs[i].Name < pkg.Structs[j].Name
	})
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, pkg); err != nil {
		return err
	}
	src, err := format.Source(buf.Bytes())
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, outFile), src, 0644)
}
